import app from 'flarum/forum/app';
import DiscussionControls from 'flarum/forum/utils/DiscussionControls';

/**
 * Telefon "Fotoğraf paylaş" akışı (onaylı maket 6), 1. adım: fotoğraf seçimi.
 * Tam ekran: büyük önizleme + 4 sütunlu seçim ızgarası (seçim sırası numaralı), "Yeni tartışma / Bu başlığa ekle".
 * "İleri" ile seçilen fotoğraflar yazma penceresindeki Upload & EXIF yükleme düğmesine aktarılır;
 * 2. adım (imza + Framio AI künye) ve 3. adım (başlık + kategori) eklentinin kendi ekranlarıyla sürer.
 */
let host = null;
export function openShareFlow() {
  if (!app.session.user) {
    flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal').then(mod => app.modal.show(mod.default));
    return;
  }
  if (host) return;
  host = document.createElement('div');
  host.className = 'MobileShare-mount';
  document.body.appendChild(host);
  document.documentElement.classList.add('MobileShare-open');
  const discussion = app.current.get('discussion');
  const state = {
    files: [],
    urls: [],
    selected: [],
    preview: 0,
    // Bir tartışmadaysak varsayılan: o başlığa ekle
    target: discussion ? 'reply' : 'new',
    discussion
  };
  const close = () => {
    state.urls.forEach(u => URL.revokeObjectURL(u));
    m.mount(host, null);
    host.remove();
    host = null;
    document.documentElement.classList.remove('MobileShare-open');
    window.removeEventListener('popstate', onPop);
  };
  const onPop = () => close();
  history.pushState({
    mobileShare: true
  }, '');
  window.addEventListener('popstate', onPop);
  const input = document.createElement('input');
  input.type = 'file';
  input.multiple = true;
  input.accept = 'image/*';
  input.onchange = () => {
    const added = Array.from(input.files || []);
    added.forEach(f => {
      state.files.push(f);
      state.urls.push(URL.createObjectURL(f));
      state.selected.push(state.files.length - 1);
    });
    if (state.selected.length) state.preview = state.selected[0];
    input.value = '';
    m.redraw();
  };
  const pick = () => input.click();

  // Seçili değilse seç ve önizle; seçili ve önizlenen kareye ikinci dokunuş seçimi kaldırır;
  // seçili ama önizlenmeyen kare yalnızca önizlenir
  const toggle = i => {
    const at = state.selected.indexOf(i);
    if (at === -1) state.selected.push(i);else if (state.preview === i) state.selected.splice(at, 1);
    state.preview = i;
  };
  const next = () => {
    const files = state.selected.map(i => state.files[i]);
    if (!files.length) return;
    const target = state.target;
    const discussionModel = state.discussion;
    history.back();
    // Geri tuşu kaydı (popstate) kapandıktan sonra yazma penceresi açılır
    setTimeout(() => startComposer(files, target, discussionModel), 60);
  };
  m.mount(host, {
    view: () => {
      const has = state.files.length > 0;
      const count = state.selected.length;
      return m("div", {
        className: "MobileShare",
        role: "dialog",
        "aria-label": "Foto\u011Fraf payla\u015F"
      }, m("div", {
        className: "MobileShare-top"
      }, m("button", {
        type: "button",
        className: "MobileShare-x",
        "aria-label": "Vazge\xE7",
        onclick: () => history.back()
      }, "\u2715"), m("b", null, "Yeni payla\u015F\u0131m"), m("button", {
        type: "button",
        className: "MobileShare-next",
        disabled: !count,
        onclick: next
      }, "\u0130leri")), m("div", {
        className: "MobileShare-steps"
      }, m("i", {
        className: "on"
      }), m("i", null), m("i", null)), state.discussion ? m("div", {
        className: "MobileShare-target"
      }, m("button", {
        type: "button",
        className: state.target === 'new' ? 'on' : '',
        onclick: () => {
          state.target = 'new';
        }
      }, "Yeni tart\u0131\u015Fma"), m("button", {
        type: "button",
        className: state.target === 'reply' ? 'on' : '',
        onclick: () => {
          state.target = 'reply';
        }
      }, "Bu ba\u015Fl\u0131\u011Fa ekle")) : null, m("div", {
        className: "MobileShare-scroll"
      }, has ? m("div", {
        className: "MobileShare-preview",
        style: {
          backgroundImage: 'url(' + state.urls[state.preview] + ')'
        }
      }, count ? m("span", null, (state.selected.indexOf(state.preview) + 1 || '–') + ' / ' + count) : null) : m("button", {
        type: "button",
        className: "MobileShare-empty",
        onclick: pick
      }, m("i", {
        className: "icon fas fa-images"
      }), m("b", null, "Foto\u011Fraf se\xE7"), m("small", null, "Galeriden bir ya da birden \xE7ok foto\u011Fraf se\xE7")), has ? m("div", {
        className: "MobileShare-grid"
      }, m("button", {
        type: "button",
        className: "MobileShare-add",
        onclick: pick,
        "aria-label": "Foto\u011Fraf ekle"
      }, m("i", {
        className: "icon fas fa-plus"
      })), state.files.map((f, i) => {
        const n = state.selected.indexOf(i);
        return m("button", {
          type: "button",
          className: 'MobileShare-tile' + (n !== -1 ? ' sel' : '') + (state.preview === i ? ' cur' : ''),
          style: {
            backgroundImage: 'url(' + state.urls[i] + ')'
          },
          onclick: () => toggle(i),
          "aria-label": f.name
        }, n !== -1 ? m("span", null, n + 1) : null);
      })) : null, has ? m("p", {
        className: "MobileShare-hint"
      }, "Sonraki ad\u0131mda imza ve Framio AI k\xFCnyesi, ard\u0131ndan ba\u015Fl\u0131k ve kategori.") : null));
    }
  });

  // Ekran açılır açılmaz telefonun galerisi açılsın
  setTimeout(pick, 50);
}

/**
 * 2. ve 3. adım: yazma penceresi açılır, seçilen fotoğraflar Upload & EXIF'in yükleme düğmesine
 * (aynı change olayı) aktarılır; imza ve künye ekranları eklentinin kendi akışıyla açılır.
 */
function startComposer(files, target, discussion) {
  const open = () => {
    if (target === 'reply' && discussion) {
      const r = DiscussionControls.replyAction.call(discussion, true, false);
      return r && r.then ? r : Promise.resolve();
    }
    return flarum.reg.asyncModuleImport('flarum/forum/components/DiscussionComposer').then(mod => {
      app.composer.load(mod.default, {
        user: app.session.user
      });
      app.composer.show();
    });
  };
  open().then(() => {
    // Paylaşım ekranı (3. adım) bu pencerede baştan açık olsun: masaüstü düzeni hiç görünmez
    app.composer.mobileShare = true;
    m.redraw();
    let tries = 0;
    const feed = () => {
      const input = document.querySelector('.Composer .spotter-upload-button input[type=file]');
      if (!input) {
        if (++tries < 40) return setTimeout(feed, 100);
        app.alerts.show({
          type: 'error'
        }, 'Yükleme düğmesi bulunamadı; fotoğrafları yazma penceresindeki 📷 ile ekleyebilirsin.');
        return;
      }
      try {
        const dt = new DataTransfer();
        files.forEach(f => dt.items.add(f));
        input.files = dt.files;
        input.dispatchEvent(new Event('change', {
          bubbles: true
        }));
      } catch (e) {
        app.alerts.show({
          type: 'error'
        }, 'Fotoğraflar aktarılamadı; yazma penceresindeki 📷 ile ekleyebilirsin.');
      }
    };
    feed();
  }).catch(() => {});
}
flarum.reg.add('framio-custom-homepage', 'forum/components/MobileShareFlow', { openShareFlow: openShareFlow, });