import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';

/**
 * Fotoğraf paylaş akışı (maket 6), 3. adım: yazma penceresinin üstünde telefon paylaşım ekranı.
 * Ham BBCode metni yerine fotoğraf önizlemesi + künye kartı + başlık + kategori + Paylaş.
 * Veri yazma penceresinin kendisinde kalır (fields.content / title / tags); gönderme, pencerenin kendi
 * gönder düğmesiyle yapılır. "Metni düzenle" ham düzenleyiciyi gösterir.
 */
export default class MobileComposeSheet extends Component {
  view() {
    const c = app.composer;
    const phone = window.matchMedia('(max-width: 767px)').matches;
    // Pencere kapanınca "Metni düzenle" tercihi sıfırlanır: bir sonraki paylaşım yine bu ekranla açılır
    if (c && c.isVisible && !c.isVisible()) {
      c.mobileRaw = undefined;
      c.mobileShare = undefined;
    }
    const content = c && c.fields && c.fields.content ? c.fields.content() || '' : '';
    const hasPhotos = /\[framio-image\b/i.test(content);
    // Paylaş akışından açılan pencerede ekran baştan açıktır (masaüstü düzeni bir an bile görünmez);
    // bir pencere (imza, künye, kategori seçimi…) açıkken geçici olarak gizlenir, o pencere üstte kalır
    const modalOpen = !!(app.modal && app.modal.isModalOpen && app.modal.isModalOpen());
    const visible = phone && c && c.isVisible && c.isVisible() && (hasPhotos || c.mobileShare) && c.mobileRaw !== true && !modalOpen;
    document.documentElement.classList.toggle('MobileCompose-open', !!visible);
    if (!visible) return m("div", {
      className: "MobileCompose-off"
    });

    // Önizleme verisi metinden: görseller ve künye satırları
    const images = [...content.matchAll(/\[framio-image\b[^\]]*?url="([^"]+)"/gi)].map(x => x[1]);
    const kunye = [...content.matchAll(/^-\s*\*\*(.+?)\*\*\s*$/gm)].map(x => x[1]);
    const isDiscussion = !!c.fields.title;
    const title = isDiscussion ? c.fields.title() || '' : '';
    const tags = (c.fields.tags || []).filter(Boolean);
    if (this.index === undefined || this.index >= images.length) this.index = 0;
    return m("div", {
      className: "MobileCompose",
      role: "dialog",
      "aria-label": "Payla\u015F\u0131m\u0131 tamamla"
    }, m("div", {
      className: "MobileShare-top"
    }, m("button", {
      type: "button",
      className: "MobileShare-x",
      "aria-label": "Kapat",
      onclick: () => this.exit()
    }, "\u2715"), m("b", null, isDiscussion ? 'Yeni paylaşım' : 'Yanıt'), m("button", {
      type: "button",
      className: "MobileShare-next",
      disabled: !images.length,
      onclick: () => this.submit()
    }, "Payla\u015F")), m("div", {
      className: "MobileShare-steps"
    }, m("i", {
      className: "on"
    }), m("i", {
      className: "on"
    }), m("i", {
      className: "on"
    })), m("div", {
      className: "MobileShare-scroll"
    }, !images.length ? m("div", {
      className: "MobileCompose-wait"
    }, m("div", {
      className: "MobileCompose-slide MobileCompose-shimmer"
    }), m("p", null, "Foto\u011Fraflar y\xFCkleniyor, imza ve k\xFCnye haz\u0131rlan\u0131yor\u2026")) : null, images.length ? m("div", {
      className: "MobileCompose-media"
    }, m("div", {
      className: "MobileCompose-track",
      onscroll: e => {
        const n = Math.round(e.target.scrollLeft / e.target.clientWidth);
        if (n !== this.index) {
          this.index = n;
          m.redraw();
        }
      }
    }, images.map(src => m("div", {
      className: "MobileCompose-slide",
      style: {
        backgroundImage: 'url(' + src + ')'
      }
    }))), images.length > 1 ? m("span", {
      className: "MobileCompose-count"
    }, this.index + 1 + ' / ' + images.length) : null) : null, kunye.length ? m("div", {
      className: "MobileCompose-box"
    }, m("div", {
      className: "MobileCompose-label"
    }, "K\xFCnye"), m("ul", {
      className: "MobileCompose-kunye"
    }, kunye.slice(0, 12).map(k => m("li", null, k)))) : null, isDiscussion ? m("div", {
      className: "MobileCompose-box"
    }, m("label", {
      className: "MobileCompose-label",
      for: "mc-title"
    }, "Ba\u015Fl\u0131k"), m("input", {
      id: "mc-title",
      className: "MobileCompose-input",
      placeholder: "\xD6rn. Lisinya Tur MAN Lion's Coach",
      value: title,
      oninput: e => c.fields.title(e.target.value)
    })) : null, isDiscussion ? m("div", {
      className: "MobileCompose-box"
    }, m("div", {
      className: "MobileCompose-label"
    }, "Kategori"), m("button", {
      type: "button",
      className: "MobileCompose-tags",
      onclick: () => this.pickTags()
    }, tags.length ? tags.map(t => m("span", {
      className: "MobileCompose-tag",
      style: {
        background: t.color() || 'var(--control-bg)'
      }
    }, t.name())) : m("span", {
      className: "MobileCompose-placeholder"
    }, "Kategori se\xE7"), m("i", {
      className: "icon fas fa-chevron-right"
    }))) : null, m("button", {
      type: "button",
      className: "MobileCompose-raw",
      onclick: () => {
        c.mobileRaw = true;
      }
    }, m("i", {
      className: "icon fas fa-code"
    }), " Metni d\xFCzenle")));
  }

  // Kategori seçimi: Tags eklentisinin yazma penceresindeki kendi düğmesi (aynı modal ve kurallar)
  pickTags() {
    const btn = document.querySelector('.Composer .DiscussionComposer-changeTags');
    if (btn) btn.click();
  }

  // Gönderme: yazma penceresinin kendi gönder düğmesi (doğrulama ve kaydetme aynı kalır)
  submit() {
    const c = app.composer;
    if (c.fields.title && !String(c.fields.title() || '').trim()) {
      app.alerts.show({
        type: 'error'
      }, 'Lütfen bir başlık yaz.');
      const el = document.getElementById('mc-title');
      if (el) el.focus();
      return;
    }
    const btn = document.querySelector('.Composer .item-submit .Button, .Composer .item-submit button');
    if (btn) btn.click();else app.alerts.show({
      type: 'error'
    }, 'Gönder düğmesi bulunamadı; "Metni düzenle" ile ekrandan gönderebilirsin.');
  }
  exit() {
    app.composer.mobileRaw = true;
    // Yazma penceresinin kendi kapatma onayı (taslak / vazgeç) çalışsın
    const close = document.querySelector('.Composer .item-close .Button, .Composer .item-close button');
    if (close) close.click();else app.composer.close();
    // Kapatma onayından vazgeçilirse paylaşım ekranı geri gelir
    setTimeout(() => {
      app.composer.mobileRaw = undefined;
      m.redraw();
    }, 400);
  }
}
flarum.reg.add('framio-custom-homepage', 'forum/components/MobileComposeSheet', MobileComposeSheet);